def probs(p):
    c={3:0,4:0,5:0}
    for bits in itertools.product([0,1], repeat=5):
        pr=1.0
        for b in bits: pr*= p if b else (1-p)
        # max run len
        m=0;cur=0
        for b in bits:
            if b: cur+=1; m=max(m,cur)
            else: cur=0
        if m in c: c[m]+=pr
    return c
for p in [0.19802,0.06931]:
    print(p, probs(p))
